var aiUi=require("$:/plugins/huwiki/ai/i18n.js");
/*\
title: $:/plugins/huwiki/ai/workbench-widget.js
type: application/javascript
module-type: widget

HUWiki AI workbench: native TiddlyWiki widget. No React, secrets or injected HTML.
\*/
(function(){
"use strict";
var consent=require("$:/plugins/huwiki/ai/consent.js");
var Widget=require("$:/core/modules/widgets/widget.js").widget;
var engine=require("$:/plugins/huwiki/ai/engine.js");
var adapters=require("$:/plugins/huwiki/ai/model-adapters.js");
var KEY="huwiki-ai-settings-v0.1";
function currentOrigin(){
  try{return window.location.origin || "(ukendt)";}catch(e){return "(ukendt)";}
}
function Workbench(parseTreeNode,options){this.initialise(parseTreeNode,options);}
Workbench.prototype=new Widget();
function make(parent,tag,klass,text){
  var el=parent.ownerDocument.createElement(tag);
  if(klass)el.className=klass;
  if(text!==undefined && text!==null)el.textContent=String(text);
  parent.appendChild(el);
  return el;
}
function loadSettings(){
  try {var x=JSON.parse(window.localStorage.getItem(KEY)||"{}");return x&&typeof x==="object"?x:{};}catch(e){return {};}
}
function persist(s){try{window.localStorage.setItem(KEY,JSON.stringify(s));}catch(e){}}
function setMessage(self,message,isError){self.message=message;self.isError=!!isError;self.draw();}
function button(parent,label,action,kind){
  var b=make(parent,"button","huwiki-ai-button"+(kind?" huw-ai-"+kind:""),label);
  b.type="button";b.addEventListener("click",action);return b;
}
function field(parent,label,value,onChange,placeholder){
  var wrap=make(parent,"label","huwiki-ai-field");
  make(wrap,"span","huwiki-ai-label",label);
  var input=make(wrap,"input","huwiki-ai-input");
  input.value=value||"";input.placeholder=placeholder||"";
  input.addEventListener("input",function(){onChange(input.value);});
  return input;
}
function textarea(parent,label,value,onChange){
  var wrap=make(parent,"label","huwiki-ai-field");
  make(wrap,"span","huwiki-ai-label",label);
  var el=make(wrap,"textarea","huwiki-ai-textarea");
  el.value=value||"";el.rows=5;
  el.addEventListener("input",function(){onChange(el.value);});
  return el;
}
function check(parent,label,checked,onChange){
  var wrap=make(parent,"label","huwiki-ai-checkrow");
  var c=make(wrap,"input");c.type="checkbox";c.checked=!!checked;
  make(wrap,"span",null,label);
  c.addEventListener("change",function(){onChange(c.checked);});
  return c;
}
Workbench.prototype.render=function(parent,nextSibling){this.computeAttributes();if(aiUi.reuseWidget(this,parent,nextSibling,"workbench-widget.js"))return;
  this.parentDomNode=parent;this.computeAttributes();this.execute();
  this.settings=loadSettings();
  this.settings.provider=this.settings.provider||"demo";
  // Import existing v0.1.2 Ollama settings without mixing provider credentials/models.
  this.settings.ollamaUrl=this.settings.ollamaUrl || this.settings.url || adapters.config("ollama").defaultUrl;
  this.settings.ollamaModel=this.settings.ollamaModel || this.settings.model || "";
  this.settings.lmstudioUrl=this.settings.lmstudioUrl || adapters.config("lmstudio").defaultUrl;
  this.settings.lmstudioModel=this.settings.lmstudioModel || "";
  this.availableModels={ollama:[],lmstudio:[],openai:[],gemini:[],claude:[]};
  this.vaultConnections=[];this.vaultReady=false;this.vaultLoading=false;
  this.settings.vaultModels=this.settings.vaultModels||{};
  this.settings.connectionMode=this.settings.connectionMode||"vault";
  this.settings.tag=this.settings.tag||"Projekt";
  this.selection=null;this.plan=null;this.message="";this.isError=false;this.loading=false;this.lastHistory=null;
  this.root=this.document.createElement("div");this.root.className="huwiki-ai-workbench";
  parent.insertBefore(this.root,nextSibling);this.domNodes=[this.root];this.draw();
  // Fetch only metadata from explicitly approved ForgeShare connections.
  this.loadPrivateConnections();
};
Workbench.prototype.execute=function(){};
Workbench.prototype.refresh=function(changedTiddlers){if(this._aiUiDelegate)return this._aiUiDelegate.refresh(changedTiddlers);
  // Keep unsaved proposals and user choices while the wiki synchronises other tiddlers.
  if(changedTiddlers&&changedTiddlers["$:/language"]){this.draw();return true;}return false;
};
Workbench.prototype.draw=function(){
  var self=this,root=this.root;if(!root)return;
  while(root.firstChild)root.removeChild(root.firstChild);
  consent.notice(root);
  var head=make(root,"div","huwiki-ai-heading");
  make(head,"h2",null,aiUi.text("HUWiki AI · Ændringsværksted"));
  make(head,"p","huwiki-ai-muted",aiUi.text("Analysér → Gennemse forslag → Godkend → Fortryd"));
  if(this.message){make(root,"div",this.isError?"huwiki-ai-message huw-ai-error":"huwiki-ai-message",aiUi.message(this.message));}
  var setup=make(root,"section","huwiki-ai-card");
  make(setup,"h3",null,aiUi.text("1. Vælg motor og tiddlere"));
  var active=this.activePrivateConnection();
  if(!this.vaultReady)make(setup,"p","huwiki-ai-muted",aiUi.text("Henter personlige forbindelser fra ForgeShare-nøgleboksen…"));
  if(this.vaultReady && this.vaultConnections.length) {
    var vaultRow=make(setup,"label","huwiki-ai-field");
    make(vaultRow,"span","huwiki-ai-label",aiUi.text("Mine gemte AI-forbindelser"));
    var vaultSelect=make(vaultRow,"select","huwiki-ai-input");
    this.vaultConnections.forEach(function(c){
      var opt=make(vaultSelect,"option",null,c.name+" · "+adapters.providerLabel(c.provider));opt.value=c.id;
    });
    var manualOpt=make(vaultSelect,"option",null,aiUi.text("Manuel lokal forbindelse / forslagstest"));manualOpt.value="manual";
    vaultSelect.value=active?active.id:"manual";
    vaultSelect.addEventListener("change",function(){
      if(vaultSelect.value==="manual")self.settings.connectionMode="manual";
      else {self.settings.connectionMode="vault";self.settings.vaultId=vaultSelect.value;}
      persist(self.settings);self.selection=null;self.plan=null;self.draw();
    });
    make(setup,"p","huwiki-ai-help",aiUi.text("Forbindelserne hentes fra dit personlige skab i denne HUWiki-platform. Ingen nøgler overføres til wikien."));
    button(setup,aiUi.text("Opdatér listen"),function(){self.loadPrivateConnections(true);},"secondary");
  } else if(this.vaultReady && !this.vaultConnections.length){
    make(setup,"p","huwiki-ai-help",aiUi.text("Ingen gemte forbindelser fundet. Tilføj dem i ForgeShare-nøgleboksen på ForgeShare, eller brug en manuel forbindelse herunder."));
    button(setup,aiUi.text("Søg efter gemte forbindelser"),function(){self.loadPrivateConnections(true);},"secondary");
  }
  if(active) {
    make(setup,"h4",null,active.name);
    make(setup,"p","huwiki-ai-help",adapters.providerLabel(active.provider)+
      (adapters.isCloud(active.provider)?aiUi.text(" · API-nøglen bliver på din computer."):" · "+active.serverUrl));
    var models=this.availableModels[active.provider];
    var selectedModel=this.selectedVaultModel(active);
    field(setup,"Model",selectedModel,function(v){
      self.settings.vaultModels[active.id]=v.trim();persist(self.settings);
    },active.provider==="lmstudio"?"google/gemma-4-e4b":aiUi.text("Vælg model"));
    if(models && models.length){
      var foundRow=make(setup,"label","huwiki-ai-field");
      make(foundRow,"span","huwiki-ai-label",aiUi.text("Vælg fundet model"));
      var foundSelect=make(foundRow,"select","huwiki-ai-input");
      models.forEach(function(name){var opt=make(foundSelect,"option",null,name);opt.value=name;});
      foundSelect.value=selectedModel;
      foundSelect.addEventListener("change",function(){
        self.settings.vaultModels[active.id]=foundSelect.value;persist(self.settings);self.draw();
      });
    }
    var vaultActions=make(setup,"div","huwiki-ai-actions");
    button(vaultActions,this.loading?aiUi.text("Tester…"):aiUi.text("Test forbindelse / vis modeller"),function(){self.testConnection();},"secondary").disabled=this.loading;
    make(setup,"p","huwiki-ai-help",aiUi.text("Navn, adresse og API-nøgle redigeres i ForgeShare-nøgleboksen på ForgeShare."));
  } else {
    var providerRow=make(setup,"label","huwiki-ai-field");
    make(providerRow,"span","huwiki-ai-label",aiUi.text("AI-motor (manuel)"));
    var select=make(providerRow,"select","huwiki-ai-input");
    [["demo",aiUi.text("Lokal forslagstest (ingen AI)")],["ollama",aiUi.text("Ollama · lokal modelserver")],["lmstudio",aiUi.text("LM Studio · OpenAI-kompatibel")]].forEach(function(p){
      var opt=make(select,"option",null,p[1]);opt.value=p[0];
    });
    select.value=this.settings.provider;
    select.addEventListener("change",function(){self.settings.provider=select.value;persist(self.settings);self.plan=null;self.selection=null;self.draw();});
    if(this.settings.provider!=="demo"){
      var provider=this.settings.provider;
      var isLM=provider==="lmstudio";
      var urlKey=isLM?"lmstudioUrl":"ollamaUrl", modelKey=isLM?"lmstudioModel":"ollamaModel";
      field(setup,isLM?"LM Studio-server":"Ollama-server",this.settings[urlKey],function(v){
        self.settings[urlKey]=v.trim();self.availableModels[provider]=[];persist(self.settings);
      },isLM?"https://din-mac.tailnet.ts.net:8443":"https://din-mac.tailnet.ts.net");
      field(setup,aiUi.text("Model (præcist ID)"),this.settings[modelKey],function(v){self.settings[modelKey]=v.trim();persist(self.settings);},isLM?"google/gemma-4-e4b":"gemma4:e4b");
      var localModels=this.availableModels[provider];
      if(localModels && localModels.length){
        var modelRow=make(setup,"label","huwiki-ai-field");
        make(modelRow,"span","huwiki-ai-label",aiUi.text("Vælg fundet model"));
        var modelSelect=make(modelRow,"select","huwiki-ai-input");
        localModels.forEach(function(name){var option=make(modelSelect,"option",null,name);option.value=name;});
        modelSelect.value=this.settings[modelKey];
        modelSelect.addEventListener("change",function(){self.settings[modelKey]=modelSelect.value;persist(self.settings);self.draw();});
      }
      var testRow=make(setup,"div","huwiki-ai-actions");
      button(testRow,this.loading?aiUi.text("Tester…"):aiUi.text("Test forbindelse / vis modeller"),function(){self.testConnection();},"secondary").disabled=this.loading;
      make(setup,"p","huwiki-ai-help",isLM?
        aiUi.text("LM Studio: brug HTTPS-adressen fra Tailscale Serve med port 8443 (uden /v1)."):
        aiUi.text("Ollama: brug din Tailscale HTTPS-adresse uden /api. HTTP kan være blokeret i HTTPS-wikier."));
      var originWrap=make(setup,"label","huwiki-ai-field");
      make(originWrap,"span","huwiki-ai-label",aiUi.text("Webadressens origin (CORS)"));
      var originBox=make(originWrap,"input","huwiki-ai-input");
      originBox.value=currentOrigin();originBox.readOnly=true;
      originBox.addEventListener("click",function(){originBox.select();});
    } else make(setup,"p","huwiki-ai-help",aiUi.text("Forslagstest bruger lokale tekstregler og kalder ingen AI-model."));
  }
  field(setup,aiUi.text("Tag for arbejdsområde"),this.settings.tag,function(v){self.settings.tag=v.trim();persist(self.settings);self.selection=null;self.plan=null;},"Projekt");
  var actions=make(setup,"div","huwiki-ai-actions");
  var gen=button(actions,this.loading?aiUi.text("Arbejder…"):aiUi.text("Analysér og lav forslag"),function(){self.analyze();},"primary");
  gen.disabled=this.loading;
  var testArea=make(setup,"div","huwiki-ai-demo-setup");
  button(testArea,aiUi.text("Opret 4 testtiddlere"),function(){
    try {
      var result=engine.createDemo($tw.wiki,$tw.Tiddler,self.settings.tag);
      // Source selection is now stale if it predates the new tiddlers.
      self.selection=null;self.plan=null;
      setMessage(self,result.created.length+" nye eksempel-tiddlere oprettet med tagget '"+result.tag+"' og oprettelsesdato. " +
        (result.skipped.length?result.skipped.length+" fandtes allerede med tagget. ":"")+
        aiUi.text("Ingen eksisterende tiddlere blev ændret. Vælg Analysér og lav forslag."),false);
    }catch(e){setMessage(self,e.message,true);}
  },"secondary");
  make(testArea,"p","huwiki-ai-help",aiUi.text("Opretter et eksempelprojekt med korrekte tags og datoer. Eksisterende tiddlere overskrives aldrig."));
  if(this.selection){
    make(setup,"p","huwiki-ai-muted",aiUi.text("Analyseret: ")+this.selection.sources.length+aiUi.text(" af ")+this.selection.total+aiUi.text(" tiddlere. ")+(this.selection.limited?aiUi.text("Højst 20 medtages pr. analyse. "):"")+(this.selection.excluded?this.selection.excluded+aiUi.text(" udeladt efter sikkerhedsfilter."):""));
  }
  if(this.plan){this.drawProposal(root);}
  this.drawHistory(root);
};
Workbench.prototype.activePrivateConnection=function(){
  if(this.settings.connectionMode!=="vault")return null;
  var id=this.settings.vaultId;
  for(var i=0;i<this.vaultConnections.length;i++)if(this.vaultConnections[i].id===id)return this.vaultConnections[i];
  return null;
};
Workbench.prototype.selectedVaultModel=function(c){
  return String(this.settings.vaultModels[c.id]||c.model||"").trim();
};
Workbench.prototype.vaultRpc=require("$:/plugins/huwiki/ai/forgeshare.js").rpc;
Workbench.prototype.loadPrivateConnections=function(force){
  var self=this;
  if(this.vaultLoading)return;
  this.vaultLoading=true;
  this.vaultRpc("huPrivateVaultList").then(function(res){
    self.vaultConnections=Array.isArray(res&&res.connections)?res.connections.filter(function(c){return c&&c.id&&adapters.supportedProvider(c.provider);}):[];
    self.vaultReady=true;
    if(self.vaultConnections.length){
      // Start with the user's first configured connection, unless manual mode was explicitly chosen.
      if(self.settings.connectionMode==="vault" && !self.activePrivateConnection()) {
        self.settings.vaultId=self.vaultConnections[0].id;
        persist(self.settings);
      }
    }else self.settings.connectionMode="manual";
    if(force){self.message=self.vaultConnections.length+" personlige AI-forbindelser fundet.";self.isError=false;}
  }).catch(function(e){
    self.vaultReady=true;
    self.settings.connectionMode="manual";
    if(force){self.message=aiUi.text("Kunne ikke hente det private skab: ")+(e.message||e);self.isError=true;}
  }).then(function(){self.vaultLoading=false;self.draw();});
};
Workbench.prototype.getConnectionSettings=function(){
  var c=this.activePrivateConnection();
  if(c){
    if(adapters.isCloud(c.provider) && !c.hasKey)throw new Error(aiUi.text("Tilføj en API-nøgle til '")+c.name+"' i ForgeShare-nøgleboksen.");
    return {provider:c.provider,id:c.id,viaVault:true,
      url:adapters.isCloud(c.provider)?"":adapters.normalizeUrl(c.serverUrl),
      model:this.selectedVaultModel(c),modelKey:c.id};
  }
  var provider=this.settings.provider;
  if(provider==="demo")throw new Error(aiUi.text("Vælg en AI-motor først."));
  var isLM=provider==="lmstudio",key=isLM?"lmstudioUrl":"ollamaUrl";
  var modelKey=isLM?"lmstudioModel":"ollamaModel";
  return {provider:provider,url:adapters.normalizeUrl(this.settings[key]),model:this.settings[modelKey]||"",modelKey:modelKey};
};
Workbench.prototype.testConnection=function(){
  var self=this,settings;
  try{settings=this.getConnectionSettings();}catch(e){setMessage(this,e.message,true);return;}
  this.loading=true;this.draw();
  var task;
  if(settings.viaVault) {
    task=this.vaultRpc("huPrivateVaultAiModels",settings.id).then(function(data){
      if(!data||!data.ok)throw new Error(data&&data.message||aiUi.text("API-nøglen blev ikke godkendt."));
      return data.models||[];
    });
  } else {
    task=fetch(adapters.modelsEndpoint(settings.provider,settings.url),{method:"GET",mode:"cors",cache:"no-store"})
      .then(function(r){if(!r.ok)return r.text().then(function(t){throw new Error(adapters.explainHttpError(settings.provider,r.status,t));});return r.json();})
      .then(function(data){return adapters.parseModels(settings.provider,data);});
  }
  task.then(function(names){
    self.availableModels[settings.provider]=names;
    var selected=adapters.isCloud(settings.provider)?adapters.preferCloudModel(settings.provider,names,settings.model):adapters.preferModel(names,settings.model);
    if(selected){
      if(settings.viaVault)self.settings.vaultModels[settings.id]=selected;
      else self.settings[settings.modelKey]=selected;
      persist(self.settings);
    }
    self.message=names.length?aiUi.text("Forbundet til ")+adapters.providerLabel(settings.provider)+". Fundet "+names.length+" modeller. Valgt: "+selected+aiUi.text(". Ingen tiddlere blev sendt."):
      aiUi.text("Forbundet, men ingen modeller blev fundet. Kontroller forbindelsens modelvalg.");
    self.isError=false;
  }).catch(function(e){
    self.message=aiUi.text("Forbindelsestesten fejlede: ")+(e.message||e)+". Kontrollér den gemte forbindelse og eventuelle browser/CORS-regler.";
    self.isError=true;
  }).then(function(){self.loading=false;self.draw();});
};
Workbench.prototype.analyze=function(){
  var self=this,s,settings;
  try{s=engine.sourceList($tw.wiki,this.settings.tag);}catch(e){setMessage(this,e.message,true);return;}
  if(!s.sources.length){setMessage(this,aiUi.text("Ingen almindelige tiddlere med dette tag blev fundet. Opret eller vælg et tag med indhold."),true);return;}
  this.selection=s;this.plan=null;this.message="";this.loading=true;this.draw();
  if(!this.activePrivateConnection() && this.settings.provider==="demo"){
    this.plan=engine.offlinePlan(s);this.loading=false;
    setMessage(this,aiUi.text("Forslag klar (lokal regelbaseret test – ikke AI). Gennemgå alt, før du gemmer."),false);return;
  }
  try{settings=this.getConnectionSettings();}catch(e){this.loading=false;setMessage(this,e.message,true);return;}
  var messages=engine.promptFor(s,($tw && $tw.version)||"ukendt"),task;
  var approval=consent.approve(settings,{da:aiUi.text("Tekst fra ")+s.sources.length+aiUi.text(" valgte tiddlere samt AI-instruktioner. Forslag gemmes først, når du vælger det."),en:"Text from "+s.sources.length+" selected tiddlers and AI instructions. Proposals are saved only when you choose."});
  if(!approval){this.loading=false;this.draw();return;}
  if(settings.viaVault){
    task=this.vaultRpc("huPrivateVaultAiGenerate",{consent:approval,connectionId:settings.id,model:settings.model,messages:messages})
      .then(function(data){if(!data||!data.ok)throw new Error(aiUi.text("AI-kaldet blev afvist."));return data.content;});
  }else{
    try{
      var request=adapters.completionRequest(settings.provider,settings.model,messages);
      var endpoint=adapters.chatEndpoint(settings.provider,settings.url);
    }catch(e){this.loading=false;setMessage(this,e.message,true);return;}
    task=fetch(endpoint,{method:"POST",mode:"cors",headers:{"Content-Type":"application/json"},body:JSON.stringify(request)})
      .then(function(r){if(!r.ok)return r.text().then(function(t){throw new Error(adapters.explainHttpError(settings.provider,r.status,t));});return r.json();})
      .then(function(data){return adapters.parseCompletion(settings.provider,data);});
  }
  task.then(function(content){
    self.plan=engine.sanitizePlan(adapters.parsePlanJSON(content),s);
    self.message=aiUi.text("AI-forslag fra ")+settings.model+aiUi.text(" er klar. Intet er gemt. Gennemgå alle ændringer.");self.isError=false;
  }).catch(function(e){self.message=aiUi.text("AI-analysen mislykkedes: ")+(e.message||e)+aiUi.text(". Ingen tiddlere er ændret.");self.isError=true;
  }).then(function(){self.loading=false;self.draw();});
};
Workbench.prototype.drawProposal=function(root){
  var self=this,p=this.plan;
  var section=make(root,"section","huwiki-ai-card");
  make(section,"h3",null,aiUi.text("2. Gennemse ændringerne"));
  make(section,"p","huwiki-ai-help",aiUi.text("Forslagene ligger kun i denne visning, indtil du trykker Gem valgte. Fjernelse af tags understøttes ikke i første version."));
  var ov=make(section,"div","huwiki-ai-proposal");
  check(ov,aiUi.text("Opret projektoversigt"),p.overview.selected,function(v){p.overview.selected=v;self.draw();});
  field(ov,aiUi.text("Titel"),p.overview.title,function(v){p.overview.title=v;},aiUi.text("Oversigt – Projekt"));
  textarea(ov,aiUi.text("Sammenfatning (ren tekst)"),p.overview.summary,function(v){p.overview.summary=v;});
  make(ov,"p","huwiki-ai-help",aiUi.text("Den nye tiddler får en dynamisk liste over alle tiddlere med tagget '")+p.scopeTag+aiUi.text("'. Indhold fra modellen køres ikke som wikitext."));
  var tagArea=make(section,"div","huwiki-ai-proposal");
  make(tagArea,"h4",null,aiUi.text("Tagforslag (")+p.tagChanges.length+")");
  if(!p.tagChanges.length)make(tagArea,"p","huwiki-ai-muted",aiUi.text("Ingen nye tags foreslået."));
  p.tagChanges.forEach(function(c){
    var row=make(tagArea,"div","huwiki-ai-tag-card");
    check(row,c.title,c.selected,function(v){c.selected=v;self.draw();});
    make(row,"div","huwiki-ai-muted",aiUi.text("Foreslået tag: ")+c.addTags.join(", "));
    if(c.reason)make(row,"div","huwiki-ai-help",c.reason);
    field(row,aiUi.text("Redigér nyt tag"),c.addTags.join(", "),function(v){c.addTags=engine.sanitizeTags(v.split(","));},"Tag");
  });
  var n=(p.overview.selected?1:0)+p.tagChanges.filter(function(c){return c.selected;}).length;
  var actions=make(section,"div","huwiki-ai-actions");
  button(actions,aiUi.text("Gem valgte ændringer (")+n+")",function(){self.approve();},"primary").disabled=n===0;
  button(actions,aiUi.text("Kassér forslag"),function(){self.plan=null;self.selection=null;setMessage(self,aiUi.text("Forslagene er kasseret. Ingen ændringer blev gemt."),false);},"secondary");
};
Workbench.prototype.approve=function(){
  if(!this.plan||!this.selection)return;
  try{
    var result=engine.commit($tw.wiki,$tw.Tiddler,this.plan,this.selection);
    this.lastHistory=result.historyTitle;this.plan=null;this.selection=null;
    setMessage(this,result.count+aiUi.text(" ændringer er skrevet til den lokale TiddlyWiki. Synkronisering til HUWiki/Google Drive er IKKE bekræftet af dette plugin."),false);
  }catch(e){setMessage(this,aiUi.text("Ingen godkendt ændringspakke: ")+e.message,true);}
};
Workbench.prototype.drawHistory=function(root){
  var self=this,section=make(root,"section","huwiki-ai-card");
  make(section,"h3",null,aiUi.text("3. Historik og fortryd"));
  var titles=($tw.wiki.getTiddlersWithTag("$:/tags/HUWikiAI/History")||[]).slice(-8).reverse();
  if(!titles.length){make(section,"p","huwiki-ai-muted",aiUi.text("Ingen ændringer gemt fra dette værksted endnu."));return;}
  titles.forEach(function(title){
    var t=$tw.wiki.getTiddler(title),record;
    if(!t)return;
    try{record=JSON.parse(t.fields.text);}catch(e){return;}
    var line=make(section,"div","huwiki-ai-history-row");
    make(line,"span",null,record.sourceTag+" · "+record.operationCount+aiUi.text(" ændringer · ")+record.status);
    if(record.status==="applied"){
      button(line,aiUi.text("Fortryd"),function(){
